static lstr L5206 = {-1, 8847, "// std/test runtime. Emitted only when a module imports std/test.\012//\012// Test.panics runs the closure in a child process (POSIX fork). The child\012// sets narra_panic_fd, so a panic writes its message to a pipe and exits\012// 101. The parent reads the pipe until it closes, waits for the child and\012// checks how it ended. The child's heap is a copy, so nothing it allocates\012// counts in the parent's leak check.\012//\012// The child gets a timeout (alarm), 10 seconds or NARRA_TEST_TIMEOUT, so a\012// closure that never returns fails instead of hanging the run. This also\012// bounds a nested child that would keep the pipe open.\012//\012// The failure paths free what they built, except the final message, which\012// narra_panic prints before the process ends.\012#include <errno.h>\012#include <signal.h>\012#include <sys/types.h>\012#include <sys/wait.h>\012\012typedef struct narra_test_proc {\012  pid_t pid;\012  int fd;\012  unsigned timeout;\012} narra_test_proc;\012\012static unsigned narra_test_timeout(void) {\012  unsigned limit = 10;\012  const char* s = getenv(\"NARRA_TEST_TIMEOUT\");\012  if (s && *s) {\012    char* end;\012    long v = strtol(s, &end, 10);\012    if (*end == 0 && v > 0 && v < 100000) limit = (unsigned)v;\012  }\012  // Inside a test that has a time limit (an alarm is pending), the closure\012  // gets what is left minus one second, at least one, so its own timeout\012  // message comes before the test's.\012  unsigned left = alarm(0);\012  if (left) {\012    alarm(left);\012    unsigned budget = left > 2 \077 left - 1 : 1;\012    if (budget < limit) limit = budget;\012  }\012  return limit;\012}\012\012// narra_test_fork returns true in the child, which must call the closure\012// and then narra_test_returned. It returns false in the parent.\012static bool narra_test_fork(narra_test_proc* t, const char* where) {\012  int fds[2];\012  fflush(stdout);\012  fflush(stderr);\012  t->timeout = narra_test_timeout();\012  if (pipe(fds) != 0) narra_panic(where, \"Test.panics: cannot create a pipe\");\012  pid_t pid = fork();\012  if (pid < 0) narra_panic(where, \"Test.panics: cannot fork\");\012  if (pid == 0) {\012    close(fds[0]);\012    narra_panic_fd = fds[1];\012    narra_panic_pos = 0;\012    alarm(t->timeout);\012    return true;\012  }\012  close(fds[1]);\012  t->pid = pid;\012  t->fd = fds[0];\012  return false;\012}\012\012// narra_test_returned ends the child when the closure returned.\012static void narra_test_returned(void) {\012  fflush(stdout);\012  _exit(0);\012}\012\012// narra_test_expect waits for the child and panics unless it panicked with\012// a message that contains want (any message when want is NULL). An empty\012// want matches any message, and the match stops at a NUL byte in either.\012static void narra_test_expect(narra_test_proc* t, lstr* want, const char* where) {\012  size_t cap = 256, len = 0;\012  char* msg = malloc(cap);\012  if (!msg) narra_panic(\"runtime\", \"out of memory\");\012  for (;;) {\012    if (len + 1 == cap) {\012      cap *= 2;\012      char* grown = realloc(msg, cap);\012      if (!grown) narra_panic(\"runtime\", \"out of memory\");\012      msg = grown;\012    }\012    ssize_t n = read(t->fd, msg + len, cap - 1 - len);\012    if (n < 0 && errno == EINTR) continue;\012    if (n <= 0) break;\012    len += (size_t)n;\012  }\012  msg[len] = 0;\012  close(t->fd);\012  int status = 0;\012  while (waitpid(t->pid, &status, 0) < 0) {\012    if (errno != EINTR) narra_panic(where, \"Test.panics: cannot wait for the child process\");\012  }\012  char buf[160];\012  const char* fail = NULL;\012  if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {\012    fail = \"expected a panic, but the function returned\";\012  } else if (!WIFEXITED(status) || WEXITSTATUS(status) != 101) {\012    if (WIFSIGNALED(status) && WTERMSIG(status) == SIGALRM) {\012      snprintf(buf, sizeof buf, \"expected a panic, but the function ran past the %u s timeout\", t->timeout);\012    } else if (WIFSIGNALED(status)) {\012      snprintf(buf, sizeof buf, \"expected a panic, but the function was killed by signal %d\", WTERMSIG(status));\012    } else {\012      snprintf(buf, sizeof buf, \"expected a panic, but the function exited with code %d\", WEXITSTATUS(status));\012    }\012    fail = buf;\012  }\012  if (fail) {\012    free(msg);\012    narra_panic(where, fail);\012  }\012  if (want && !strstr(msg, want->data)) {\012    lstr* w = narra_show_string(want);\012    lstr* g = narra_quote(msg, (int64_t)len, '\"');\012    size_t n = (size_t)w->len + (size_t)g->len + 64;\012    char* out = malloc(n);\012    if (!out) narra_panic(\"runtime\", \"out of memory\");\012    snprintf(out, n, \"expected a panic containing %s, got %s\", w->data, g->data);\012    lstr_release(w);\012    lstr_release(g);\012    free(msg);\012    narra_panic(where, out);\012  }\012  free(msg);\012}\012\012// The failure of Test.eq. The shown values are owned and released here.\012static void narra_test_fail_eq(lstr* expected, lstr* actual, const char* where) {\012  size_t n = (size_t)expected->len + (size_t)actual->len + 32;\012  char* out = malloc(n);\012  if (!out) narra_panic(\"runtime\", \"out of memory\");\012  snprintf(out, n, \"expected %s, got %s\", expected->data, actual->data);\012  lstr_release(expected);\012  lstr_release(actual);\012  narra_panic(where, out);\012}\012\012static void narra_test_fail_ne(lstr* value, const char* where) {\012  size_t n = (size_t)value->len + 48;\012  char* out = malloc(n);\012  if (!out) narra_panic(\"runtime\", \"out of memory\");\012  snprintf(out, n, \"expected a value other than %s\", value->data);\012  lstr_release(value);\012  narra_panic(where, out);\012}\012\012// Test.golden: compare actual with <dir>/<name>.golden. With\012// NARRA_UPDATE_GOLDEN=1 the file is written instead.\012#include <sys/stat.h>\012\012static void narra_test_golden(lstr* name, lstr* actual, const char* where) {\012  const char* dir = narra_golden_dir;\012  const char* up = getenv(\"NARRA_UPDATE_GOLDEN\");\012  int update = up && strcmp(up, \"1\") == 0;\012  if (name->len == 0) narra_panic(where, \"Test.golden: the name is empty\");\012  int bad = memchr(name->data, 0, (size_t)name->len) != NULL || name->data[0] == '/';\012  // No path segment may be \"..\".\012  for (const char* s = name->data; !bad && *s;) {\012    const char* e = strchr(s, '/');\012    size_t k = e \077 (size_t)(e - s) : strlen(s);\012    if (k == 2 && s[0] == '.' && s[1] == '.') bad = 1;\012    s += k + (e \077 1 : 0);\012    if (!e) break;\012  }\012  if (bad) narra_panic(where, \"Test.golden: the name must be a relative path without a `..` segment\");\012  size_t cap = strlen(dir) + (size_t)name->len + 160;\012  char* path = malloc(cap);\012  if (!path) narra_panic(\"runtime\", \"out of memory\");\012  snprintf(path, cap, \"%s/%s.golden\", dir, name->data);\012  if (update) {\012    // Create the directories on the way.\012    mkdir(dir, 0777);\012    for (char* p = path + strlen(dir) + 1; *p; p++) {\012      if (*p == '/') {\012        *p = 0;\012        mkdir(path, 0777);\012        *p = '/';\012      }\012    }\012    FILE* f = fopen(path, \"wb\");\012    if (!f || fwrite(actual->data, 1, (size_t)actual->len, f) != (size_t)actual->len) {\012      char* out = malloc(cap + 48);\012      if (!out) narra_panic(\"runtime\", \"out of memory\");\012      snprintf(out, cap + 48, \"Test.golden: cannot write %s.golden\", name->data);\012      if (f) fclose(f);\012      free(path);\012      narra_panic(where, out);\012    }\012    fclose(f);\012    free(path);\012    return;\012  }\012  FILE* f = fopen(path, \"rb\");\012  if (!f) {\012    // The message names the golden file, not the directory, so test output\012    // does not depend on where the package is.\012    char* out = malloc(cap + 96);\012    if (!out) narra_panic(\"runtime\", \"out of memory\");\012    snprintf(out, cap + 96, \"golden file %s.golden does not exist; run with NARRA_UPDATE_GOLDEN=1 to create it\", name->data);\012    free(path);\012    narra_panic(where, out);\012  }\012  size_t wcap = 4096, wlen = 0;\012  char* want = malloc(wcap);\012  if (!want) narra_panic(\"runtime\", \"out of memory\");\012  for (;;) {\012    if (wlen == wcap) {\012      wcap *= 2;\012      want = realloc(want, wcap);\012      if (!want) narra_panic(\"runtime\", \"out of memory\");\012    }\012    size_t n = fread(want + wlen, 1, wcap - wlen, f);\012    if (n == 0) break;\012    wlen += n;\012  }\012  fclose(f);\012  const char* got = actual->data;\012  size_t glen = (size_t)actual->len;\012  size_t i = 0;\012  while (i < wlen && i < glen && want[i] == got[i]) i++;\012  if (i == wlen && i == glen) {\012    free(want);\012    free(path);\012    return;\012  }\012  // The first differing line: both lines start after the last newline before i.\012  size_t start = i;\012  int64_t line = 1;\012  for (size_t k = 0; k < i; k++) if (want[k] == '\\n') line++;\012  while (start > 0 && want[start - 1] != '\\n') start--;\012  size_t we = start, ge = start;\012  while (we < wlen && want[we] != '\\n') we++;\012  while (ge < glen && got[ge] != '\\n') ge++;\012  lstr* w = narra_quote(want + start, (int64_t)(we - start), '\"');\012  lstr* g = narra_quote(got + start, (int64_t)(ge - start), '\"');\012  size_t n = (size_t)w->len + (size_t)g->len + (size_t)name->len + 96;\012  char* out = malloc(n);\012  if (!out) narra_panic(\"runtime\", \"out of memory\");\012  snprintf(out, n, \"golden %s differs at line %lld: expected %s, got %s\", name->data, (long long)line, w->data, g->data);\012  lstr_release(w);\012  lstr_release(g);\012  free(want);\012  free(path);\012  narra_panic(where, out);\012}\012"};
